PRAGMA page_size=1024; BEGIN; CREATE TABLE t1(rowid INTEGER PRIMARY KEY, i INTEGER, t TEXT); CREATE TABLE t2(rowid INTEGER PRIMARY KEY, i INTEGER, t TEXT); CREATE TABLE t3(rowid INTEGER PRIMARY KEY, i INTEGER, t TEXT); WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n<50000), data(n,x) AS (SELECT n, ((n*1103515245+12345)%2147483648)%50000 FROM seq) INSERT INTO t1 SELECT n,x,printf('n%05d',x) FROM data; WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n<50000), data(n,x) AS (SELECT n, ((n*1103515245+67890)%2147483648)%50000 FROM seq) INSERT INTO t2 SELECT n,x,printf('n%05d',x) FROM data; WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n<50000), data(n,x) AS (SELECT n, ((n*1103515245+13579)%2147483648)%50000 FROM seq) INSERT INTO t3 SELECT n,x,printf('n%05d',x) FROM data; CREATE INDEX i1 ON t1(t); CREATE INDEX i2 ON t2(t); CREATE INDEX i3 ON t3(t); CREATE VIEW v1 AS SELECT rowid,i,t FROM t1; CREATE VIEW v2 AS SELECT rowid,i,t FROM t2; CREATE VIEW v3 AS SELECT rowid,i,t FROM t3; COMMIT;